const fs = require('fs');

const basePath = '/home/aichath/Tek2/G-AIA-410-COT-4-1-persona-22/persona';
const usersDir = `${basePath}/users`;

// Lire tous les fichiers utilisateurs
const files = fs.readdirSync(usersDir).filter(f => f.endsWith('.json'));

const users = [];
files.forEach(file => {
  const user = JSON.parse(fs.readFileSync(`${usersDir}/${file}`, 'utf8'));
  if (user.active === true) {
    users.push(user);
  }
});

return users.map(user => ({ json: user }));

